SELECT p.gender, p.anchor_year, p.anchor_year_group, i.intime, i.outtime, i.los, d.drg_mortality, COUNT(DISTINCT pr.procedure_id) AS procedure_count, percent_rank() OVER (ORDER BY COUNT(DISTINCT pr.procedure_id)) AS procedure_percentile_rank, percent_rank() OVER (ORDER BY i.los) AS los_percentile_rank, SUM(CASE WHEN d.drg_mortality = 'Y' THEN 1 ELSE 0 END)::FLOAT / NULLIF(COUNT(DISTINCT i.subject_id), 0) AS mortality_rate FROM patients p JOIN icustays i ON p.subject_id = i.subject_id JOIN diagnoses_icd d ON i.hadm_id = d.hadm_id JOIN procedures_icd pr ON i.hadm_id = pr.subject_id AND i.intime <= pr.chartdate AND i.outtime >= pr.chartdate WHERE p.gender = 'M' AND p.anchor_year BETWEEN 39 AND 49 AND d.drg_code = 'DKA' AND i.intime >= CURRENT_DATE - INTERVAL '24 hours' GROUP BY p.gender, p.anchor_year, p.anchor_year_group, i.intime, i.outtime, i.los, d.drg_mortality ORDER BY procedure_percentile_rank NULLS LAST, los_percentile_rank NULLS LAST;